let child = value.guard.take().unwrap_or_default();
self.frames.push(Frame::Attach(Attach::TaggedContinuationGuard { parent: mem::take(value), limit }));
self.frames.push(Frame::Node(Node::Par { value: child, limit: child_limit }));
