pub fn decode_par<B: Buf>(buf: B) -> Result<Par, DecodeError> {
    decode_par_with_stats(buf).map(|(value, _stats)| value)
}

pub(crate) fn decode_par_deferred_epathmap_validation<B: Buf>(buf: B) -> Result<Par, DecodeError> {
    decode_par_with_epathmap_validation(buf, false).map(|(value, _stats)| value)
}

pub fn decode_par_with_stats<B: Buf>(
    buf: B,
) -> Result<(Par, DecodeStats), DecodeError> {
    decode_par_with_epathmap_validation(buf, true)
}

fn decode_par_with_epathmap_validation<B: Buf>(
    buf: B,
    validate_epathmaps: bool,
) -> Result<(Par, DecodeStats), DecodeError> {
    // Exact canonical recursive shapes with a byte-native proof can be
    // imported directly as one authoritative ParBag endpoint. Reconstructing
    // every nested Par would copy, hash, and discard all encoded suffixes,
    // producing quadratic work at EPathMap boundaries. The recognizers consume
    // nothing; every other byte shape continues through the complete generated
    // machine below.
    if buf.chunk().len() == buf.remaining() {
        if let Some(value) =
            crate::rust::par_bag::import_canonical_parbag_fast_path(buf.chunk())
        {
            #[cfg(feature = "phase7-depth-histograms")]
            crate::rust::rholang::phase7_depth_histogram::record_par("protobuf_decoder", &value);
            return Ok((
                value,
                DecodeStats {
                    max_frames: 1,
                    max_values: 1,
                },
            ));
        }
    }
    let mut machine = Machine::new(
        buf,
        Node::Par {
            value: Par::default(),
            limit: 0,
        },
        validate_epathmaps,
    );
    machine.run()?;
    if machine.values.len() != 1 {
        panic!(
            "protobuf decoder invariant: Par left {} root values",
            machine.values.len()
        );
    }
    let stats = machine.stats;
    match machine
        .values
        .pop()
        .expect("the single checked Par root exists")
    {
        Value::Par(value) => {
            #[cfg(feature = "phase7-depth-histograms")]
            crate::rust::rholang::phase7_depth_histogram::record_par("protobuf_decoder", &value);
            Ok((value, stats))
        }
        other => {
            let found = other.kind_name();
            machine.values.push(other);
            panic!("protobuf decoder invariant: expected Par, found {found}");
        }
    }
}


